mapper.sql:
WHERE P.STATUS = 'ON_SALE'
AND ( LOWER(P.PRODUCT_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(B.BUSINESS_NAME) LIKE '%' || LOWER(#{keyword}) || '%' )
AND P.PRODUCT_TYPE IN
#{productType}
AND FLOOR( P.PRICE * (100 - NVL(P.DISCOUNT_RATE, 0)) / 100 ) >= #{minPrice}
AND FLOOR( P.PRICE * (100 - NVL(P.DISCOUNT_RATE, 0)) / 100 ) <= #{maxPrice}
AND NVL(P.DISCOUNT_RATE, 0) > 0
AND NVL(P.STOCK, 0) > 0

mapper.select:
SELECT PAGED.PRODUCT_NO, PAGED.BUSINESS_NO, PAGED.CONTENT_NO, PAGED.ACTOR_NO, PAGED.PRODUCT_NAME, PAGED.PRODUCT_TYPE, PAGED.PRICE, PAGED.DISCOUNT_RATE, PAGED.STOCK, PAGED.DESCRIPTION, PAGED.STATUS, PAGED.BUSINESS_NAME, PAGED.MAIN_IMAGE FROM ( SELECT ROW_NUMBER() OVER ( ORDER BY P.CREATED_AT DESC, P.PRODUCT_NO DESC ) AS RN, P.PRODUCT_NO, P.BUSINESS_NO, P.CONTENT_NO, P.ACTOR_NO, P.PRODUCT_NAME, P.PRODUCT_TYPE, P.PRICE, NVL(P.DISCOUNT_RATE, 0) AS DISCOUNT_RATE, NVL(P.STOCK, 0) AS STOCK, P.DESCRIPTION, P.STATUS, B.BUSINESS_NAME, PI.MAIN_IMAGE FROM PRODUCT P
INNER JOIN BUSINESS B ON B.BUSINESS_NO = P.BUSINESS_NO
) PAGED
WHERE PAGED.RN BETWEEN #{startRow} AND #{endRow}
ORDER BY PAGED.RN
